def q(s): return '"'+s.replace('"','""')+'"'
def table(n,fields,version,checks=(),unique=(),pk=None):
    cols=[]; fks=[]
    for field in fields.split():
        name,typ=field.split(':',1); target=None
        if '@' in typ: typ,target=typ.split('@',1)
        nullable=typ.endswith('?'); typ=typ.rstrip('?'); default=None
        if '=' in typ:typ,default=typ.split('=',1)
        # suffix ? means nullable. Integers marked p are identity primary keys; k is non-identity PK.
        kind={'p':'INTEGER','k':'INTEGER','i':'INTEGER','b':'INTEGER','t':'TEXT','d':'TEXT','u':'TEXT','x':'BLOB','r':'BLOB','n':'NUMERIC'}[typ]
        sql=q(name)+' '+kind
        if typ=='p':sql+=' PRIMARY KEY AUTOINCREMENT'
        elif typ=='k':sql+=' PRIMARY KEY NOT NULL'
        elif not nullable:sql+=' NOT NULL'
        if typ=='r':sql+=' DEFAULT (randomblob(8))'
        elif default=='now':sql+=" DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))"
        elif default=='uuid':sql+=" DEFAULT (lower(hex(randomblob(16))))"
        elif default is not None:sql+=' DEFAULT '+(default if default.isdigit() else "'"+default.replace("'","''")+"'")
        if typ=='b':sql+=' CHECK ('+q(name)+' IN (0,1))'
        if typ=='x':sql+=' CHECK (length('+q(name)+')=32)'
        if typ=='r':sql+=' CHECK (length('+q(name)+')=8)'
        cols.append(sql)
        if target:
            dst,col=target.rsplit('.',1);fks.append(f'FOREIGN KEY ({q(name)}) REFERENCES {q(dst.replace(".","__"))} ({q(col)})')
    if pk:cols.append('PRIMARY KEY ('+','.join(map(q,pk.split(',')))+')')
    for u in unique:cols.append('UNIQUE ('+','.join(map(q,u.split(',')))+')')
    cols+=fks+['CHECK ('+c+')' for c in checks]
    SCHEMA[n]={'version':version,'sql':'CREATE TABLE '+q(n.replace('.','__'))+' (\n  '+',\n  '.join(cols)+'\n);','columns_dsl':fields}
