    def ins(n,cols,row):db.execute('INSERT INTO '+q(n.replace('.','__'))+' ('+','.join(map(q,cols))+') VALUES ('+','.join('?' for _ in cols)+')',row)
    for n,cols,row in SEEDS:ins(n,cols,row)
